// Формирует Telegram-дайджест по статистике за прошедшие 7 дней.
const r = $input.first().json;
const lines = [
  '📊 *Еженедельный дайджест CRM*',
  '',
  `🆕 Новые брифы: *${r.new_briefs ?? 0}*`,
  `👨‍💼 Взято в работу: *${r.taken_in_work ?? 0}*`,
  `✅ Завершено: *${r.completed ?? 0}*`,
  '',
  `📂 В работе сейчас: *${r.in_progress_total ?? 0}*`,
  `🔓 Без менеджера: *${r.unassigned_total ?? 0}*`,
];
return [{ json: { text: lines.join('\n') } }];
